-- data/rows/magie.sql : export déterministe, une instruction par ligne, triée par (id). NE PAS ÉDITER À LA MAIN.
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-de-la-corruption', 'Corruption', 'corruption', 'Corruption', 4, NULL, 'La magie de la Corruption est l''antithèse de l’Arcane, une énergie négative qui ne connaît ni faiblesse ni résistance. Semblable à l''Arcane, elle se manifeste sous une forme brute et malléable, mais son essence est pervertie par une volonté malveillante qui cherche à affaiblir, entraver et tuer. Contrairement aux autres formes de magie, la Corruption ne se mélange à aucune autre : elle est une entité à part entière qui refuse toute fusion, sauf entre les mains des Elfes Charbons et des Felfes Noirs, qui possèdent un lien et une histoire avec elle.

Tout comme la magie de l’Arcane, la Corruption offre une grande polyvalence, permettant à ses utilisateurs de s’adapter à toutes les situations. Mais là où l’Arcane façonne et construit, la Corruption érode et consume. Ses adeptes sont craints non pas pour leur force brute, mais pour leur capacité à manipuler l’affaiblissement et le désespoir. Ils sont perçus comme des combattants impitoyables et méthodiques, préférant saper leurs ennemis de l’intérieur plutôt que d’engager un combat frontal.', 'Les utilisateurs de la corruption sont marqués surtout au niveau des cheveux et du corps, les cheveux possèdent des mèches de couleur noire et le corps est parsemé de tatouages couleur anthracite qui deviennent noirs aussi quand un sort est utilisé, plus il y a de puissance, plus les tatouages sont de plus en plus noirs.', 'L''utilisateur de la corruption est un combattant qui fait énormément de dégâts et utilise énormément d''entrave. Il utilise le Chakra et la Corruption comme un système de vases communicants.

Chaque sort demande du chakra, à chaque utilisation d''un sort, le coût en chakra se transfère dans la corruption (si un sort coûte 4, vous obtenez 4 corruption), il est possible d''utiliser cette réserve de corruption pour lancer les mêmes sorts mais avec des effets supplémentaires mais il faut consommer le double du coût en corruption (si le sort coûte 4, il vous faut 8 corruption). Bien entendu ceux qui sont de la corruption sont totalement immunisés à l''effet négatif du trop-plein de corruption (qui est la transformation en abomination solvité, donc une mort du personnage) mais prudence, car quand on est gavé de corruption cela se voit physiquement sur le personnage et la corruption reste une magie mal vue.

Attention, si le chakra permet d''obtenir de la corruption, l''inverse ne se fait pas. Et la corruption n''empiète pas dans l''espace du chakra.', 0, 8, 'intelligence', 'INTELLIGENCE', NULL, NULL, NULL, NULL, 'Toutes les magies ne peuvent pas se combiner avec la corruption, c''est mono-magie uniquement. Seuls les Elfes noirs (Charbon) et les Felfes noirs peuvent cette magie en innée/acquis avec une autre magie (les limitations de la magie acquise s''appliquent pour les magies primordiales : Pas d''arcane, sang ou espace/temps)', 'magies', 'Magie Maverick V8 › Corruption › A1:AJ73', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-de-la-foudre', 'Foudre', 'foudre', 'Foudre', 13, NULL, 'La magie de la foudre est une magie spécialisée dans les dégâts et l''amplification. Héritée du Dieu de la Foudre, le Dieu-Scientifique des nains, elle combine puissance destructrice et maîtrise des énergies électriques.

Les utilisateurs de la foudre manipulent l''électricité pour lancer des éclairs, déchaîner des orages ou surcharger leurs capacités et celles de leurs alliés. Rapide et violente, cette magie excelle dans les offensives fulgurantes et les techniques visant à amplifier les performances au-delà de leurs limites habituelles.

Associée à l''excitation, une émotion liée à l''élan et à la frénésie, la magie de la foudre attire souvent les individus curieux, audacieux et toujours en quête de nouvelles découvertes ou sensations.', 'Les utilisateurs de la foudre ont les mèches jaunes, les yeux jaunes lors de l''utilisation d''un sort, de l’électricité parcourt en permanence leur corps. Des plaques de fer très conductrices se trouvent sur certaines parties du corps (bras, jambes, organes vitaux).', NULL, 0, 5, 'agilite', 'AGILITÉ', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Foudre › A1:AJ53', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-de-la-glace', 'Glace', 'glace', 'Glace', 10, NULL, 'La magie de la glace est l''une des formes les plus étonnantes de magie dans Maverick. Les mages qui maîtrisent cette magie sont capables de manipuler la glace et le froid pour créer des formes de glace incroyablement complexes et belles.
Les utilisateurs de la glace peuvent utiliser leur pouvoir pour créer des ponts de glace, des lames de glace tranchantes, des murs de glace qui peuvent repousser les ennemis ou les protéger des attaques.
Les utilisateurs de la glace peuvent également utiliser leur magie pour geler l''eau ou l''humidité dans l''air, créant des tempêtes de neige et des blizzards qui peuvent aveugler leurs ennemis. Ils peuvent également utiliser leur pouvoir pour rafraîchir des objets, des boissons ou des aliments, ou pour purifier l''eau en la transformant en glace.
Les utilisateurs de la glace sont souvent considérés comme des personnages calmes et réfléchis, en raison de la nature froide de leur magie.', 'Les utilisateurs de la glace ont les mèches bleu cyan, des cheveux assez courts en général, les yeux bleu cyan lors de l''utilisation d''un sort. Certaines parties du corps présentent des plaques de glace, elles sont généralement sur les membres ou les zones vitales.', NULL, 0, 5, 'intelligence', 'INTELLIGENCE', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Glace › A1:AJ53', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-de-la-lumiere', 'Lumière', 'lumiere', 'Lumière', 14, NULL, 'La magie de la lumière est une magie spécialisée dans le soin et la protection. Héritée de la Déesse de la Lumière, une divinité de bonté et de guérison, elle est considérée comme l''une des magies les plus efficaces pour préserver la vie.

Les utilisateurs de la lumière emploient leur pouvoir pour soigner les blessures, purifier les altérations d''état et protéger leurs alliés. Cette magie peut également renforcer les capacités d''un groupe et se montrer redoutable contre les créatures vulnérables à la lumière.

Associée à l''espoir, une émotion liée à la foi et au fanatisme, la magie de la lumière est souvent pratiquée par ceux qui souhaitent guider, protéger et soutenir les autres face à l''adversité.', 'Les utilisateurs de la Lumière ont des cheveux avec les mèches beiges, les yeux beiges lors d''une utilisation de sort. Certains possèdent une petite aura de lumière qui émane des membres, d''autres ont les bracelets de lumière d''Aurora et d''autres possèdent une paire d''ailes de lumière (la déesse en possède 10)', NULL, 0, 5, 'perception', 'PERCEPTION', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Lumière › A1:AJ53', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-de-la-necromancie', 'Nécromancie', 'necromancie', 'Nécromancie', 7, NULL, 'La magie de la nécromancie est une magie spécialisée dans l''invocation et l''entrave. Héritée de la Déesse de la Vie et de la Mort, elle permet de manipuler les forces liées au trépas, aux âmes et aux non-morts.

Les utilisateurs de la nécromancie peuvent invoquer des squelettes, des zombis et d''autres serviteurs non-morts pour combattre à leurs côtés. Ils sont également capables d''affaiblir leurs ennemis, de perturber leur vitalité ou de leur faire de bons dégâts avec le poison.

Associée au deuil, une émotion liée à l''acceptation et à la fixation, la nécromancie rappelle que la mort fait partie du cycle naturel du monde. Si certains utilisent ce pouvoir pour guider les âmes vers leur jugement, d''autres choisissent d''exploiter les morts pour satisfaire leurs propres ambitions.', 'Les nécromanciens sont généralement plus minces que la moyenne, voire maigres pour les plus anciens, avec moins de formes. Une aura verte émane de leurs mains et ils possèdent des excroissances osseuses par endroits (coude, genou, épaule, phalanges, etc.).', NULL, 5, 5, 'volonte', 'VOLONTÉ', 'ame', 'Cette magie utilise la 4ème barre. Elle possède un maximum de 10 Âmes et la régénère de 1 par tour.', 10, 1, NULL, 'magies', 'Magie Maverick V8 › Nécromancie › A1:AJ70', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-de-la-terre', 'Terre', 'terre', 'Terre', 11, NULL, 'La magie de la terre est une magie spécialisée dans la défense et le soutien. Héritée du Dieu de la Terre, une divinité patiente et loyale, elle puise sa force dans la roche, le métal, la flore et le sol lui-même.

Les utilisateurs de la terre peuvent provoquer des secousses, façonner la pierre et le métal, invoquer de puissants golems ou renforcer leur corps grâce à une armure minérale. Cette magie est également capable de soutenir ses alliés grâce aux propriétés curatives de certains sorts de la terre.

Associée à la détermination, une émotion liée à la ténacité et à l''obstination, la magie de la terre est souvent privilégiée par ceux qui avancent sans jamais céder, quelles que soient les difficultés qui se dressent devant eux.', 'Les utilisateurs de la Terre sont des personnes qui ont des tailles et une musculature plus haute que la moyenne (comme pour le sang), leurs corps possèdent de légers renforts de pierre un peu partout, les mèches sont brunes et les yeux d''un marron brillant lors de l''utilisation d''un sort.', NULL, 0, 5, 'force', 'FORCE', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Terre › A1:AJ53', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-de-larcane', 'Arcane', 'arcane', 'Arcane', 3, NULL, 'La magie de l’Arcane est l’essence pure et brute de la magie, une magie primordiale non liée aux éléments. Elle est malléable, semblable à une pâte à modeler que seuls les plus érudits savent sculpter à leur convenance. Contrairement aux autres formes de magie, l’Arcane ne possède ni faiblesses, ni résistances, la rendant d’une polyvalence absolue.

Les utilisateurs de l’Arcane sont souvent perçus comme des érudits ou des visionnaires, recherchant une compréhension totale de la magie elle-même. Bien qu’ils ne possèdent pas de spécialisations dans leur rôle, ils compensent par leur extrême adaptabilité, pouvant utiliser leurs sorts en fonction de l’ennemi ou du besoin du moment. Cette absence de limites fait de la magie de l’Arcane une des plus redoutables, mais aussi l’une des plus complexes à maîtriser. Ceux qui la dominent ne se reposent pas sur un seul atout, mais sur beaucoup de possibilités, faisant d’eux des combattants imprévisibles.', 'Les utilisateurs de l''arcane sont marqués surtout au niveau des cheveux et du corps, les cheveux possèdent des mèches de couleur argentée et le corps est parsemé de tatouages couleur argent qui deviennent blanc brillant aussi quand un sort est utilisé, plus il y a de puissance, plus les tatouages brillent.', 'Chaque sort qui possède un coût en chakra "x/tour" ne possède pas de limite de tour et va consommer du chakra tant qu''il est actif. Le lanceur doit faire un jet de magie pour pouvoir réussir son sort (normal jusque-là) et une fois le sort lancé, le sort est maintenu tant que le lanceur le décide ou qu''il perd sa concentration. Il est possible de cumuler plusieurs fois le même sort ou alors de placer le même sort sur différentes cibles, le coût par tour en sera bien plus grand vu que tout se cumule.

Perdre son sort : Si jamais une attaque est encaissée, il est nécessaire de faire un jet de magie/concentration, si jamais il est raté, la concentration est perdue et tous les sorts qui étaient actifs s''arrêtent immédiatement.

Un sort qui possède la mention : XxN/tour, veut dire que le sort va coûter un certain nombre de chakra (X) par nombre d''applications qu''il y a eu (N) par tour.
Exemple : J''ai posé sur 3 personnes différentes un sort qui coûte 3. Donc en 1 tour je vais consommer 9 chakra.', 0, 10, 'intelligence', 'INTELLIGENCE', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Arcane › A1:AJ72', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-de-leau', 'Eau', 'eau', 'Eau', 9, NULL, 'La magie de l''eau est une magie polyvalente spécialisée dans le soin, les dégâts et l''entrave. Héritée de la Déesse de l''Eau, une divinité bienveillante, elle est capable aussi bien de protéger la vie que de déchaîner la puissance des flots.

Les utilisateurs de l''eau manipulent l''eau sous toutes ses formes, influencent les courants et peuvent même perturber les marées. Cette magie permet de soigner les blessures, d''entraver les adversaires ou de les frapper avec la force de l''eau. Elle est également utilisée pour la purification, l''irrigation et de nombreuses tâches du quotidien.

Associée à l''empathie, une émotion liée à la compassion et à l''abnégation, la magie de l''eau exige responsabilité et maîtrise, car une utilisation imprudente peut provoquer d''importants dégâts ou perturber l''équilibre naturel des eaux.', 'Les spécialistes de l''eau ont les mèches bleutées, très longues et mouillées en permanence, ont un corps plus esthétique que la moyenne, ce dernier transpire de l''eau tout le temps, les yeux sont bleu azur lors de l''utilisation d''un sort.', NULL, 0, 5, 'social', 'SOCIAL', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Eau › A1:AJ53', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-de-lespace-temps', 'Espace/Temps', 'espace-temps', 'TempsEspace', 5, NULL, 'La magie de l’Espace-Temps est une magie primordiale qui dicte les lois du mouvement et de la distance. Elle permet à ses utilisateurs de plier la réalité à leur volonté, ouvrant des brèches sur le terrain ou manipulant la position de leurs ennemis et alliés en un clin d’œil.

Les utilisateurs de l’Espace-Temps peuvent, à un niveau basique, créer des portails pour se déplacer rapidement entre deux points. Les plus puissants pratiquants de cette magie sont capables de manipuler l’espace autour de leurs adversaires, les téléportant contre leur gré, les envoyant dans des pièges ou les isolant de leurs alliés.

Bien qu’elle ne soit pas une magie de destruction directe, la magie de l’Espace-Temps est l’ultime outil tactique, rendant ses utilisateurs difficiles à approcher. Ne les sous-estimez jamais, ils ont toujours un coup d''avance par rapport à vous.', 'Les utilisateurs de l''Espace/Temps possèdent d''étranges bandages de momies couleur rose sur les mains, bras (jusqu''en bas du coude), pieds et jambes (jusqu''en bas du genou) et semblent être impossibles à enlever ou détruire, comme si c''était une seconde peau. Les mèches de cheveux sont roses.', NULL, 0, 10, 'intelligence', 'INTELLIGENCE', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › TempsEspace › A1:AJ56', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-de-lombre', 'Ombre', 'ombre', 'Ombre', 15, NULL, 'La magie de l''ombre est une magie spécialisée dans l''entrave. Héritée d''Umbro, le Dieu de l''Ombre et des intrigues, elle excelle dans l''affaiblissement des adversaires et la manipulation des situations à son avantage.

Les utilisateurs de l''ombre manipulent l''obscurité pour infliger de nombreux effets négatifs, perturber leurs ennemis ou même utiliser leur ombre pour attaquer. Cette magie est particulièrement redoutable pour contrôler le déroulement d''un affrontement et exploiter les zones plongées dans les ténèbres.

Associée à la prudence, une émotion liée à la clairvoyance et à la paranoïa, la magie de l''ombre est souvent mal perçue en raison de ses liens avec la discrétion, les complots et les activités criminelles, bien que tous ses utilisateurs ne suivent pas cette voie.', 'Les utilisateurs de l''ombre ont des cheveux généralement plus courts et des mèches mauves, les yeux violets lors d''une utilisation de sort. Certains possèdent des bracelets faits d''ombre violettes, d''autres possèdent des cornes de Chakra couleur mauve (plus clair pour les femelles et plus sombre pour les mâles) si la race possède des cornes physiques : c''est une aura ténébreuse violette qui les entoure ou alors une aura sombre émane de leur main et pied.', NULL, 0, 5, 'perception', 'PERCEPTION', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Ombre › A1:AJ53', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-du-feu', 'Feu', 'feu', 'Feu', 8, NULL, 'La magie du feu est une magie offensive spécialisée dans les dégâts, l''entrave et le renforcement. Héritée du Dieu du Feu, une divinité chaotique, elle est réputée pour sa puissance destructrice et sa capacité à transformer son environnement.

Les utilisateurs du feu peuvent créer et manipuler les flammes sous de nombreuses formes. Ils sont capables d''embraser leurs ennemis, de contrôler la chaleur ou de renforcer armes et alliés grâce à une énergie brûlante. En dehors du combat, cette magie permet également d''allumer des foyers, chauffer des lieux ou alimenter certains travaux artisanaux.

Associée à l''ardeur, une émotion liée au courage et à la colère, la magie du feu reste difficile à maîtriser. Une utilisation imprudente peut rapidement devenir incontrôlable et provoquer d''importants dégâts collatéraux.', 'Les utilisateurs du feu ont certaines mèches rouges vif, les yeux rouges lors de l''utilisation d''un sort, possèdent des brûlures un peu partout sur le corps, leurs mains sont un peu calcinées (comme du bois brûlé encore chaud) et produisent du feu.', NULL, 0, 5, 'social', 'SOCIAL', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Feu › A1:AJ53', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-du-sang', 'Sang', 'sang', 'Sang', 2, NULL, 'La magie du sang est une magie spécialisée dans les dégâts. Héritée du Dieu de la Force, une divinité puissante et instinctive, elle repose sur l''utilisation de son propre sang pour déchaîner une force brute et implacable.

Les utilisateurs du sang sont capables d''amplifier leurs capacités physiques, d''accélérer leur régénération ou de transformer leur sang en arme. Cette magie privilégie l''offensive pure, permettant d''infliger de lourds dégâts tout en poussant le corps de son utilisateur au-delà de ses limites naturelles.

Associée à la passion, une émotion liée aussi bien à l''amour qu''à la haine, la magie du sang attire ceux qui vivent leurs émotions avec intensité et n''hésitent pas à tout donner pour atteindre leurs objectifs.', 'La magie du Sang marque beaucoup sur la taille et la musculature qui est plus élevée que la moyenne (comme pour la terre), les veines sont apparentes un peu partout et augmentent au fur et à mesure des niveaux de magie, les mèches des cheveux sont couleur bordeaux, les yeux sont bordeaux en combat.', NULL, 10, 0, 'force', 'FORCE', 'sang', 'Cette magie utilise la 4ème barre. Elle possède un maximum de 10 Sang et la régénère de 1 par tour.', 10, 1, NULL, 'magies', 'Magie Maverick V8 › Sang › A1:AJ59', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-du-vent', 'Vent', 'vent', 'Vent', 12, NULL, 'La magie du vent est une magie spécialisée dans le placement et les dégâts. Héritée de la Déesse du Vent, une divinité calme et éprise de liberté, elle excelle dans le contrôle des déplacements et la maîtrise du terrain.

Les utilisateurs du vent manipulent les courants d''air pour repousser, attirer ou déplacer leurs cibles. Ils peuvent créer des bourrasques, des tornades ou des tempêtes, dévier des projectiles et même utiliser les vents pour accélérer leurs déplacements ou prendre de la hauteur.

Associée à la liberté, une émotion liée à l''indépendance et à l''inconstance, la magie du vent est souvent privilégiée par ceux qui refusent les contraintes et cherchent à garder le contrôle de leurs mouvements comme de ceux de leurs adversaires.', 'Les spécialistes du Vent ont les cheveux mi-longs, mèches vert clair, les yeux vert clair lors de l''utilisation d''un sort, corps mince, leurs corps produisent un vent très léger, notamment au niveau des bras et jambes. Cette brise légère visible à l''œil nu est de couleur verte.', NULL, 0, 5, 'agilite', 'AGILITÉ', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Vent › A1:AJ53', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/magie-du-vide', 'Vide', 'vide', 'Vide', 6, NULL, 'La magie du Vide est l’antithèse de l’Espace-Temps. Cette magie est une arme redoutable entre les mains de ceux qui cherchent à neutraliser leurs adversaires, car elle ne se contente pas d’affaiblir : elle interdit, elle prive, elle réduit à néant.

Les utilisateurs du Vide possèdent un don unique : ils sont capables de bloquer l’accès à la magie elle-même. En un instant, ils peuvent tisser un voile de néant autour d’un ennemi, lui interdisant l’usage de tout pouvoir pendant un court laps de temps. Face à eux, même les plus grands mages deviennent vulnérables. En plus de ça, elle est capable d''utiliser la puissante télékinésie, ce qui leur permet un petit contrôle sur le terrain.

Les porteurs de cette magie sont immédiatement reconnaissables à leurs yeux dont le blanc est entièrement teinté de noir, un signe de leur lien profond avec le néant. Ils sont perçus comme des êtres inquiétants et impénétrables, des entités silencieuses capables d’annuler toute opposition par une simple pensée.', 'Les utilisateurs du vide ont une pilosité blanche et possèdent une inversion au niveau des yeux, le blanc de l''œil devient noir.', NULL, 0, 5, 'volonte', 'VOLONTÉ', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Vide › A1:AJ56', NULL);
INSERT INTO magie (id, nom, nom_cle, onglet, ordre, banniere, description, description_physique, explication, sante_offerte, chakra_offert, caracteristique_id, caracteristique_brut, barre4_ressource, barre4_texte, barre4_max, barre4_regen, incompatibilite_note, origine, source_ref, remarque) VALUES ('magies/potentiel-illimite', 'Potentiel Illimité', 'potentiel-illimite', 'Potentiel illimité (magie diffi', 1, 'MAGIE DIFFICILE À JOUER !!', 'Le Potentiel Illimité, aussi appelé Absolu Incomplet ou Magie Universelle, est l’essence brute de la création et de la destruction. Elle est le point de départ de toutes les autres magies, un pouvoir si vaste et si versatile qu''il est impossible de l''égaler. Les rares élus qui en héritent détiennent le couteau suisse de la magie, capable de piocher dans toutes les magies pour lancer des sorts.

Cependant, un tel pouvoir a un prix. Contrairement aux autres magies qui façonnent le monde selon des règles définies, le Potentiel Illimité est un torrent d’énergie brute, si dévastateur que le corps mortel peine à en supporter la tension. Chaque utilisation épuise l’utilisateur bien plus rapidement qu’une magie ordinaire, usant sa chair et ses os comme un feu qui consume son propre combustible. En conséquence, les porteurs de cette magie sont physiquement vulnérables, recevant deux fois plus de dégâts physiques que les autres.

Le Potentiel Illimité est à la fois une bénédiction et une malédiction, offrant une puissance absolue mais incomplète, un pouvoir sans égal mais limité par la fragilité du corps humain.', 'Des yeux dorés/oranges, ainsi que des mèches dorées. Le corps est parsemé de tatouages couleur orange qui deviennent dorés quand un sort est utilisé, plus il y a de puissance, plus les cicatrices brillent. Ils ont des physiques moins charnus que la plupart des gens et ils semblent tout le temps épuisés.', 'Le principal intérêt repose sur sa versatilité, en effet cette magie pioche ses sorts dans toutes les magies existantes. Cette versatilité a un prix qui est de ne pouvoir atteindre que le niveau 3 de puissance magique maximum en plus d''être limité à peu de races.
- Humain, Nain, Elfe argenté, Forestier, Noir, Doré, Farfadet, Felfe, Hujin et Drakos sont les seuls qui peuvent l''avoir.
- Mono-magie uniquement.
- Classe unique = Archimage.
- Surtension corporelle (Vulnérabilité contre les dégâts physiques, ne peut mettre plus de 5 Santé lors de la répartition des points lors du passage de niveau global.
- État fatigue 1 en permanence (sans le malus aux dégâts).
- Impossible de porter des armures lourdes ou boucliers lourds même si la classe vous le permet.', 0, 15, NULL, 'AU CHOIX ou ALÉATOIRE', NULL, NULL, NULL, NULL, NULL, 'magies', 'Magie Maverick V8 › Potentiel illimité (magie diffi › A1:AJ57', NULL);
